    echo $str;
    if(!preg_match(&amp;quot;/.*p.*h.*p.*/i&amp;quot;,$str))&amp;#123;
        file_put_contents($v3,$str);
    &amp;#125;
    else&amp;#123;
        die(&amp;#39;Sorry&amp;#39;);
    &amp;#125;
&amp;#125;
else&amp;#123;
