    if(!preg_match(&amp;quot;/\\\\|\/|\~|\`|\!|\@|\#|\%|\^|\*|\-|\+|\=|\&amp;#123;|\&amp;#125;|\&amp;quot;|\&amp;#39;|\,|\.|\;|\?|flag|GLOBALS|echo|var_dump|print|g|i|f|c|o|d/i&amp;quot;, $c) &amp;amp;&amp;amp; strlen($c)&amp;lt;=16)&amp;#123;
         eval(&amp;quot;$c&amp;quot;.&amp;quot;;&amp;quot;);  
