&lt;h1 id=&#34;web127&#34;&gt;&lt;a href=&#34;#web127&#34; class=&#34;headerlink&#34; title=&#34;web127&#34;&gt;&lt;/a&gt;web127&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-10 11:25:09
