include(&amp;quot;flag.php&amp;quot;);
highlight_file(__FILE__);
$ctf_show = md5($flag);
$url = $_SERVER[&amp;#39;QUERY_STRING&amp;#39;];


//特殊字符检测
function waf($url)&amp;#123;
    if(preg_match(&amp;#39;/\`|\~|\!|\@|\#|\^|\*|\(|\)|\\$|\_|\-|\+|\&amp;#123;|\;|\:|\[|\]|\&amp;#125;|\&amp;#39;|\&amp;quot;|\&amp;lt;|\,|\&amp;gt;|\.|\\\|\//&amp;#39;, $url))&amp;#123;
        return true;
    &amp;#125;else&amp;#123;
        return false;
    &amp;#125;
&amp;#125;

if(waf($url))&amp;#123;
    die(&amp;quot;嗯哼？&amp;quot;);
&amp;#125;else&amp;#123;
    extract($_GET);
&amp;#125;


if($ctf_show===&amp;#39;ilove36d&amp;#39;)&amp;#123;
    echo $flag;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?ctf show=ilove36
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250812161445197.png&#34; alt=&#34;image-20250812161445197&#34; style=&#34;zoom:25%;&#34; /&gt;

