&lt;p&gt;&lt;strong&gt;&lt;code&gt;-&amp;gt;&lt;/code&gt; 与 &lt;code&gt;::&lt;/code&gt; 调用函数的区别：&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;-&amp;gt;&lt;/code&gt; 调用对象实例方法&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt; &lt;strong&gt;&lt;code&gt;::&lt;/code&gt; 调用静态方法&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;调用类中静态函数，POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;ctfshow=ctfshow::getFlag
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250814233120051.png&#34; alt=&#34;image-20250814233120051&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web138&#34;&gt;&lt;a href=&#34;#web138&#34; class=&#34;headerlink&#34; title=&#34;web138&#34;&gt;&lt;/a&gt;web138&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-16 22:52:13

*/

error_reporting(0);
