&lt;h1 id=&#34;web144&#34;&gt;&lt;a href=&#34;#web144&#34; class=&#34;headerlink&#34; title=&#34;web144&#34;&gt;&lt;/a&gt;web144&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-18 16:21:15

*/

highlight_file(__FILE__);
if(isset($_GET[&amp;#39;v1&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v2&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v3&amp;#39;]))&amp;#123;
    $v1 = (String)$_GET[&amp;#39;v1&amp;#39;];
    $v2 = (String)$_GET[&amp;#39;v2&amp;#39;];
    $v3 = (String)$_GET[&amp;#39;v3&amp;#39;];

    if(is_numeric($v1) &amp;amp;&amp;amp; check($v3))&amp;#123;
        if(preg_match(&amp;#39;/^\W+$/&amp;#39;, $v2))&amp;#123;
            $code =  eval(&amp;quot;return $v1$v3$v2;&amp;quot;);
            echo &amp;quot;$v1$v3$v2 = &amp;quot;.$code;
        &amp;#125;
    &amp;#125;
&amp;#125;

function check($str)&amp;#123;
    return strlen($str)===1?true:false;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;check&lt;/code&gt; 函数对 &lt;code&gt;v3&lt;/code&gt; 做检测，将payload放在 &lt;code&gt;v2&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
